export function fill(template: string, fields: Record<string, string>): Filled {
  const parts: string[] = [];
  let prepared = "";
  let i = 0;
  while (i < template.length) {
    const ch = template[i];
    if (ch === "{" && template[i + 1] === "{") {
      prepared += "{{";
      i += 2;
      continue;
    }
    if (ch === "{") {
      const close = template.indexOf("}", i + 1);
      if (close < 0) {
        prepared += template.slice(i);
        break;
      }
      const inner = template.slice(i + 1, close);
      const bar = inner.indexOf("|");
      if (bar < 0) {
        prepared += template.slice(i, close + 1);
      } else {
        const name = inner.slice(0, bar).trim();
        const fallback = inner.slice(bar + 1);
        const has = Object.prototype.hasOwnProperty.call(fields, name) && typeof fields[name] === "string";
        parts.push(has ? fields[name] : fallback);
        prepared += "\u0000" + (parts.length - 1) + "\u0000";
      }
      i = close + 1;
      continue;
    }
    prepared += ch;
    i++;
  }
  const out = fillPlain(prepared, fields);
  if (parts.length === 0) return out;
  return {
    text: out.text.replace(/\u0000(\d+)\u0000/g, (_m, n: string) => parts[Number(n)]),
    missing: out.missing,
  };
}

